'use client';

import { useState } from 'react';
import { groupBy, sortBy, meanBy, sumBy, maxBy, minBy } from 'lodash';
import { mean, std, median, quantileSeq, variance } from 'mathjs';

interface Product {
  id: string;
  name: string;
  price: number;
  category: string;
  rating: number;
  reviews: number;
  inStock: boolean;
}

// Sample products to compare
